import React, { useEffect, useState, useMemo } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { resumeApi, templateApi } from '../services/api';
import { downloadResume } from '../utils/downloadResume';
import { useToast } from '../components/Toast';
import ResumeDocumentPreview from '../components/ResumeDocumentPreview';

export default function Dashboard() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const { addToast } = useToast();

  const [resumes, setResumes] = useState([]);
  const [templates, setTemplates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('ALL'); // 'ALL' | 'PUBLISHED' | 'DRAFT'
  const [previewResume, setPreviewResume] = useState(null);
  const [deletingId, setDeletingId] = useState(null);

  useEffect(() => {
    Promise.all([
      resumeApi.getAll().catch(() => ({ data: [] })),
      templateApi.getAll().catch(() => ({ data: [] }))
    ]).then(([resumesRes, templatesRes]) => {
      setResumes(resumesRes.data || []);
      setTemplates(templatesRes.data || []);
    }).catch(() => {
      setErrorMsg('Could not load dashboard data.');
    }).finally(() => {
      setLoading(false);
    });
  }, []);

  const isRecruiterLike = ['RECRUITER', 'HIRING_MANAGER', 'ADMIN'].includes(user.role);

  const calculateResumeStrength = (r) => {
    let score = 0;
    if (r.title && r.title.length > 3) score += 15;
    if (r.candidateName && r.candidateName.length > 2) score += 15;
    if (r.headline) score += 10;
    if (r.summary && r.summary.length > 30) score += 15;
    if (r.contactEmail) score += 10;
    if (r.contactPhone) score += 5;
    if (Array.isArray(r.skills) && r.skills.length >= 3) score += 15;
    if (Array.isArray(r.experience) && r.experience.length >= 1) score += 15;
    return Math.min(score, 100);
  };

  const filteredResumes = useMemo(() => {
    return resumes.filter((r) => {
      const matchesSearch =
        (r.title || '').toLowerCase().includes(searchQuery.toLowerCase()) ||
        (r.headline || '').toLowerCase().includes(searchQuery.toLowerCase()) ||
        (r.candidateName || '').toLowerCase().includes(searchQuery.toLowerCase());

      if (!matchesSearch) return false;
      if (statusFilter === 'ALL') return true;
      return (r.status || 'DRAFT').toUpperCase() === statusFilter;
    });
  }, [resumes, searchQuery, statusFilter]);

  const stats = useMemo(() => {
    const total = resumes.length;
    const published = resumes.filter((r) => r.status === 'PUBLISHED' || r.visibleToRecruiters).length;
    const avgScore = total > 0
      ? Math.round(resumes.reduce((acc, r) => acc + calculateResumeStrength(r), 0) / total)
      : 0;
    return { total, published, avgScore };
  }, [resumes]);

  const handleDelete = async (id, title) => {
    if (!window.confirm(`Are you sure you want to delete "${title || 'this resume'}"?`)) return;
    try {
      setDeletingId(id);
      await resumeApi.remove(id);
      setResumes((prev) => prev.filter((r) => r.id !== id));
      addToast(`Resume "${title || 'Untitled'}" deleted`, 'info');
      if (previewResume && previewResume.id === id) {
        setPreviewResume(null);
      }
    } catch (err) {
      addToast('Failed to delete resume', 'error');
    } finally {
      setDeletingId(null);
    }
  };

  const handleDuplicate = async (r) => {
    try {
      const duplicateData = {
        ...r,
        id: undefined,
        title: `${r.title || 'Resume'} (Copy)`,
        status: 'DRAFT',
      };
      const res = await resumeApi.create(duplicateData);
      setResumes((prev) => [res.data, ...prev]);
      addToast('Resume duplicated successfully!', 'success');
      navigate(`/resume/${res.data.id}`);
    } catch (err) {
      addToast('Could not duplicate resume', 'error');
    }
  };

  const handleDownload = (r) => {
    addToast('Generating PDF document…', 'info');
    downloadResume(r);
  };

  return (
    <div className="page-container dashboard-page">
      {/* Welcome Hero Banner */}
      <div className="dashboard-hero-banner">
        <div className="hero-content">
          <div className="hero-badge">🚀 Workspace & Career Hub</div>
          <h1 className="hero-title">Welcome back, {user.fullName.split(' ')[0]}</h1>
          <p className="hero-subtitle">
            Craft high-impact, ATS-optimized resumes with real-time visual feedback and professional templates.
          </p>
        </div>
        {!isRecruiterLike && (
          <div className="hero-actions">
            <Link to="/resume/new" className="btn-primary-glow">
              <span className="btn-icon">+</span> Create New Resume
            </Link>
            <Link to="/templates" className="btn-secondary-glass">
              🎨 Browse Templates
            </Link>
          </div>
        )}
      </div>

      {isRecruiterLike ? (
        <div className="recruiter-welcome-card">
          <div className="recruiter-card-icon">🎯</div>
          <div className="recruiter-card-body">
            <h3>Recruiter Candidate Portal</h3>
            <p>
              You're logged in as a <strong>{user.role.replace('_', ' ').toLowerCase()}</strong>. Search verified talent and discover candidates by skill and role.
            </p>
            <Link to="/recruiter" className="btn-primary" style={{ marginTop: '12px', display: 'inline-block' }}>
              🔍 Open Candidate Search
            </Link>
          </div>
        </div>
      ) : (
        <>
          {/* Quick Stats Metric Cards */}
          <div className="stats-metric-grid">
            <div className="stat-card">
              <div className="stat-icon-wrapper stat-indigo">📄</div>
              <div className="stat-info">
                <div className="stat-value">{stats.total}</div>
                <div className="stat-label">Total Resumes</div>
              </div>
            </div>

            <div className="stat-card">
              <div className="stat-icon-wrapper stat-emerald">👁️</div>
              <div className="stat-info">
                <div className="stat-value">{stats.published}</div>
                <div className="stat-label">Recruiter Visible</div>
              </div>
            </div>

            <div className="stat-card">
              <div className="stat-icon-wrapper stat-amber">⚡</div>
              <div className="stat-info">
                <div className="stat-value">{stats.avgScore}%</div>
                <div className="stat-label">Avg. Profile Strength</div>
              </div>
            </div>

            <div className="stat-card">
              <div className="stat-icon-wrapper stat-purple">🎨</div>
              <div className="stat-info">
                <div className="stat-value">{templates.length || 6}</div>
                <div className="stat-label">Templates Available</div>
              </div>
            </div>
          </div>

          {/* Search, Filter & Controls Toolbar */}
          <div className="dashboard-controls-bar">
            <div className="search-input-wrapper">
              <span className="search-icon">🔍</span>
              <input
                type="text"
                className="dashboard-search-input"
                placeholder="Search resumes by title, role, or keywords…"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
              {searchQuery && (
                <button className="clear-search-btn" onClick={() => setSearchQuery('')}>×</button>
              )}
            </div>

            <div className="filter-pills-group">
              <button
                className={`filter-pill ${statusFilter === 'ALL' ? 'active' : ''}`}
                onClick={() => setStatusFilter('ALL')}
              >
                All ({resumes.length})
              </button>
              <button
                className={`filter-pill ${statusFilter === 'PUBLISHED' ? 'active' : ''}`}
                onClick={() => setStatusFilter('PUBLISHED')}
              >
                Published ({resumes.filter((r) => r.status === 'PUBLISHED' || r.visibleToRecruiters).length})
              </button>
              <button
                className={`filter-pill ${statusFilter === 'DRAFT' ? 'active' : ''}`}
                onClick={() => setStatusFilter('DRAFT')}
              >
                Drafts ({resumes.filter((r) => r.status === 'DRAFT' && !r.visibleToRecruiters).length})
              </button>
            </div>
          </div>

          {errorMsg && <div className="error-banner">{errorMsg}</div>}

          {loading ? (
            <div className="loading-state-container">
              <div className="spinner"></div>
              <p>Loading your resumes…</p>
            </div>
          ) : filteredResumes.length === 0 ? (
            <div className="empty-state-card">
              <div className="empty-state-art">📝</div>
              <h3>{searchQuery ? 'No matching resumes found' : 'No resumes yet'}</h3>
              <p>
                {searchQuery
                  ? 'Try searching with different keywords or clear the filter.'
                  : 'Get started by creating your first resume or exploring our curated template designs.'}
              </p>
              {searchQuery ? (
                <button className="btn-secondary" onClick={() => setSearchQuery('')}>Clear Search</button>
              ) : (
                <div style={{ display: 'flex', gap: '10px', justifyContent: 'center', marginTop: '16px' }}>
                  <Link to="/resume/new" className="btn-primary">+ Create First Resume</Link>
                  <Link to="/templates" className="btn-secondary">🎨 Pick a Template</Link>
                </div>
              )}
            </div>
          ) : (
            <div className="resume-grid">
              {filteredResumes.map((r) => {
                const score = calculateResumeStrength(r);
                const matchedTemplate = templates.find((t) => Number(t.id) === Number(r.templateId)) || templates[0];

                return (
                  <div className="resume-card-pro" key={r.id}>
                    <div className="card-top-header">
                      <div className="template-pill-chip">
                        {matchedTemplate?.name || 'Executive Timeline'}
                      </div>
                      <span className={`status-badge-modern status-${(r.status || 'DRAFT').toLowerCase()}`}>
                        {r.visibleToRecruiters ? '🟢 Public' : (r.status || 'DRAFT')}
                      </span>
                    </div>

                    <div className="card-main-info">
                      <h3 className="resume-card-title">{r.title || 'Untitled Resume'}</h3>
                      <p className="resume-card-headline">{r.headline || 'No professional title set'}</p>
                    </div>

                    {/* Mini strength bar */}
                    <div className="card-strength-box">
                      <div className="strength-meta">
                        <span className="strength-label">Profile Strength</span>
                        <span className="strength-pct">{score}%</span>
                      </div>
                      <div className="strength-track">
                        <div
                          className="strength-bar-fill"
                          style={{
                            width: `${score}%`,
                            background: score > 75 ? '#10b981' : score > 45 ? '#f59e0b' : '#6366f1'
                          }}
                        ></div>
                      </div>
                    </div>

                    <div className="card-quick-meta">
                      <span className="meta-item">
                        💼 {(r.experience || []).length} Roles
                      </span>
                      <span className="meta-item">
                        🎓 {(r.education || []).length} Degrees
                      </span>
                      <span className="meta-item">
                        ⚡ {(r.skills || []).length} Skills
                      </span>
                    </div>

                    <div className="card-pro-actions">
                      <Link to={`/resume/${r.id}`} className="btn-action-primary" title="Open editor">
                        ✏️ Edit
                      </Link>

                      <button
                        type="button"
                        className="btn-action-secondary"
                        onClick={() => setPreviewResume(r)}
                        title="Quick View"
                      >
                        👁️ Preview
                      </button>

                      <button
                        type="button"
                        className="btn-action-secondary"
                        onClick={() => handleDuplicate(r)}
                        title="Duplicate this resume"
                      >
                        📑 Copy
                      </button>

                      <button
                        type="button"
                        className="btn-action-secondary"
                        onClick={() => handleDownload(r)}
                        title="Download PDF"
                      >
                        📥 PDF
                      </button>

                      <button
                        type="button"
                        className="btn-action-danger"
                        disabled={deletingId === r.id}
                        onClick={() => handleDelete(r.id, r.title)}
                        title="Delete resume"
                      >
                        🗑️
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </>
      )}

      {/* Quick Preview Modal */}
      {previewResume && (
        <div className="modal-overlay" onClick={() => setPreviewResume(null)}>
          <div className="modal-container preview-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <div className="modal-title-box">
                <h3>{previewResume.title || 'Resume Preview'}</h3>
                <span className="modal-template-tag">
                  {templates.find((t) => Number(t.id) === Number(previewResume.templateId))?.name || 'Timeline Template'}
                </span>
              </div>
              <div className="modal-actions-right">
                <Link to={`/resume/${previewResume.id}`} className="btn-primary btn-sm">
                  ✏️ Edit in Builder
                </Link>
                <button
                  type="button"
                  className="btn-secondary btn-sm"
                  onClick={() => handleDownload(previewResume)}
                >
                  📥 Download PDF
                </button>
                <button
                  type="button"
                  className="modal-close-btn"
                  onClick={() => setPreviewResume(null)}
                >
                  ✕
                </button>
              </div>
            </div>
            <div className="modal-body-scroller">
              <div className="modal-preview-wrapper">
                <ResumeDocumentPreview
                  resume={previewResume}
                  template={templates.find((t) => Number(t.id) === Number(previewResume.templateId))}
                />
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
